/** Public YouTube browsing in the same native Blades pages as the other media services. */
final class YoutubeBrowser extends View {
 final MainActivity a;final YoutubeClient ra;final Paint p=new Paint(3);final ArrayList<Item> rows=new ArrayList<>();
 int screen,index,offset,listPage;float scale=1,left,height=720,down;long stick;String heading="YouTube",listTitle="Videos",listSource="",listKey="",channelId="",channelName="",clearKey="";boolean closed;
 JSONArray entries=new JSONArray(),comments=new JSONArray();JSONObject selected;YoutubePlayer player;
 static class Item{String title,sub,body,image;Runnable run;Item(String t,String s,String b,String i,Runnable r){title=t;sub=s;body=b;image=i;run=r;}}
 YoutubeBrowser(MainActivity a){super(a);this.a=a;ra=a.youtube;setFocusableInTouchMode(true);ra.changed=()->{int selected=index,scroll=offset;build();index=Math.min(selected,Math.max(0,rows.size()-1));offset=Math.min(scroll,Math.max(0,rows.size()-slots()));invalidate();};home();}
 void add(String t,String s,String b,String i,Runnable r){rows.add(new Item(t,s,b,i,r));}
 void home(){ra.cancel();screen=0;index=offset=0;build();invalidate();}
 void page(int n){if(n==4)ra.cancel();screen=n;index=offset=0;build();invalidate();}
 String thumb(JSONObject j){return j.optString("thumbnail");}
 String subtitle(JSONObject j){long d=j.optLong("duration");return j.optString("channel")+(d>0?" · "+(d/60)+":"+String.format(Locale.ROOT,"%02d",d%60):"");}
 void local(String key,String title){ra.cancel();listKey=key;listSource="";listTitle=title;channelId="";entries=ra.list(key);page(1);}
 void browse(String source,String title,int page){ra.browse(source,page,data->{listSource=source;listKey="";listTitle=title;listPage=page;entries=data;page(1);});}
 void feed(){channelId="";ra.feed(data->{listKey="";listSource="feed";listTitle="Subscription Feed";entries=data;page(1);});}
 void channel(JSONObject video){channelId=video.optString("channel_id");channelName=video.optString("channel");String url=YoutubeClient.channelUrl(channelId);if(url.isEmpty()){ra.status="Resolve this video's channel by playing it first";invalidate();return;}browse(url+"/videos",channelName,0);}
 void build(){rows.clear();
  if(screen==0){heading="YouTube";add("Search YouTube",ra.prefs.getString("last_search",""),"Find public videos using the Blades keyboard.","",()->edit("Search YouTube",ra.prefs.getString("last_search",""),q->{if(!q.trim().isEmpty()){channelId="";ra.prefs.edit().putString("last_search",q.trim()).apply();browse("search:"+q.trim(),"Search: "+q.trim(),0);}}));add("Subscription Feed",ra.list("subscriptions").length()+" local subscriptions","Recent public uploads from channels you follow in this app.","",this::feed);add("Subscriptions","Saved on this device","Browse your followed channels. These do not change a YouTube account.","",()->page(3));add("Watch Later",ra.list("later").length()+" videos","Videos saved for another time.","",()->local("later","Watch Later"));add("Favorites",ra.list("likes").length()+" videos","Your local favorites; this does not submit likes to YouTube.","",()->local("likes","Favorites"));add("History / Continue Watching",ra.list("history").length()+" videos","Resume videos watched in this app.","",()->local("history","History"));add("Play Queue",ra.list("queue").length()+" videos","Queued videos play next when enabled in Settings.","",()->local("queue","Play Queue"));add("Open YouTube Link","Video, channel or public playlist","Enter an HTTPS YouTube link.","",()->edit("YouTube Link","",url->{if(YoutubeClient.input(url).isEmpty()){ra.status="Enter an HTTPS youtube.com or youtu.be link";invalidate();}else{channelId="";browse(url,"YouTube Link",0);}}));add("Settings","Playback and local data","Quality, queue autoplay, history and extractor updates.","",()->page(4));}
  else if(screen==1){heading=listTitle;if(!listKey.isEmpty())entries=ra.list(listKey);if(!channelId.isEmpty())add(ra.contains("subscriptions",channelId)?"Unsubscribe Locally":"Subscribe Locally",channelName,"Follow this channel on this device.","",()->{try{ra.subscription(new JSONObject().put("channel_id",channelId).put("channel",channelName));}catch(Exception ignored){}});for(int i=0;i<entries.length();i++){JSONObject item=entries.optJSONObject(i);if(item==null)continue;add(item.optString("title"),subtitle(item),item.optString("description","Select for playback and local library actions."),thumb(item),()->{selected=item;page(2);});}if(entries.length()==0)add("No videos yet","",listKey.isEmpty()?ra.status:"Add videos from search results or channel pages.","",()->{});if(!listSource.isEmpty()&&!listSource.equals("feed")){if(listPage>0)add("Previous Page","","Previous 20 videos.","",()->browse(listSource,listTitle,listPage-1));if(entries.length()>=20)add("Next Page","","Next 20 videos.","",()->browse(listSource,listTitle,listPage+1));}}
  else if(screen==2&&selected!=null){heading=selected.optString("title");long resume=ra.position(selected.optString("id"));add(resume>10000?"Resume at "+YoutubePlayer.time(resume):"Play",subtitle(selected),selected.optString("description"),thumb(selected),()->play(selected,true,listKey.equals("queue")));if(resume>10000)add("Play from Beginning","","Start this video again.",thumb(selected),()->play(selected,false,listKey.equals("queue")));add("View Channel",selected.optString("channel"),"Browse this channel's public uploads.",thumb(selected),()->channel(selected));add(ra.contains("subscriptions",selected.optString("channel_id"))?"Unsubscribe Locally":"Subscribe Locally",selected.optString("channel"),"Saved only in this app. No account required.",thumb(selected),()->ra.subscription(selected));add(ra.contains("later",selected.optString("id"))?"Remove from Watch Later":"Save to Watch Later","","Your local saved videos.",thumb(selected),()->ra.toggle("later",selected));add(ra.contains("likes",selected.optString("id"))?"Remove Favorite":"Add Favorite","Local only","Does not submit a like to YouTube.",thumb(selected),()->ra.toggle("likes",selected));add("Add to Queue",ra.list("queue").length()+" queued","Play after the current video.",thumb(selected),()->ra.enqueue(selected));add("Public Comments","Read only","Read available public comments. Posting and rating comments require a YouTube account and are not provided here.",thumb(selected),()->ra.resolve(selected,true,info->{comments=info.optJSONArray("comments");if(comments==null)comments=new JSONArray();page(5);}));}
  else if(screen==3){heading="Local Subscriptions";JSONArray subs=ra.list("subscriptions");for(int i=0;i<subs.length();i++){JSONObject sub=subs.optJSONObject(i);if(sub==null)continue;add(sub.optString("title"),"Browse uploads","Select the channel, then use Unsubscribe Locally to remove it.","",()->{channelId=sub.optString("id");channelName=sub.optString("title");browse(sub.optString("url")+"/videos",channelName,0);});}if(rows.isEmpty())add("No subscriptions yet","","Search for a video, open it, then choose Subscribe Locally.","",this::home);}
  else if(screen==4){heading="YouTube Settings";int quality=ra.prefs.getInt("quality",1080);add("Maximum Quality: "+quality+"p","Select to change","Choose the best available stream at or below this resolution. Applies when opening the next video.","",()->{int[] values={360,480,720,1080,1440,2160};int at=0;for(int i=0;i<values.length;i++)if(values[i]==quality)at=i;ra.prefs.edit().putInt("quality",values[(at+1)%values.length]).apply();build();invalidate();});add("Queue Autoplay: "+(ra.prefs.getBoolean("autoplay",true)?"On":"Off"),"Select to change","Only plays videos you explicitly added to the queue.","",()->{ra.prefs.edit().putBoolean("autoplay",!ra.prefs.getBoolean("autoplay",true)).apply();build();invalidate();});add("Save History: "+(ra.prefs.getBoolean("history_enabled",true)?"On":"Off"),"Select to change","Store viewing progress locally for resume.","",()->{ra.prefs.edit().putBoolean("history_enabled",!ra.prefs.getBoolean("history_enabled",true)).apply();build();invalidate();});add("Update yt-dlp",ra.prefs.getString("engine_version",YoutubeClient.BUNDLED),"Check the official latest stable release and verify its SHA-256 checksum before installation.","",ra::update);add("Clear History","Local viewing progress","Requires confirmation.","",()->{clearKey="history";page(6);});add("Clear Queue","Queued videos","Requires confirmation.","",()->{clearKey="queue";page(6);});add("About YouTube","No Google account or cookies","Search, public channels and videos use yt-dlp. Subscriptions, favorites, Watch Later and history are local. Age-restricted, private, members-only and sign-in-required content may not be available.","",()->{});}
  else if(screen==5){heading="Public Comments";for(int i=0;i<comments.length();i++){JSONObject item=comments.optJSONObject(i);if(item!=null)add(item.optString("author","Viewer"),item.optLong("like_count")+" likes",item.optString("text"),"",()->{});}if(rows.isEmpty())add("No comments available","","Comments may be disabled or unavailable without login.","",()->{});}
  else if(screen==6){heading="Clear "+clearKey+"?";add("Cancel","","Keep your local data.","",()->page(4));add("Clear "+clearKey,"","Only removes this app's local data.","",()->{ra.clear(clearKey);page(4);});}
 }
 void play(JSONObject item,boolean resume){play(item,resume,false);}
 void play(JSONObject item,boolean resume,boolean consume){ra.resolve(item,false,info->{if(consume)ra.removeQueued(item.optString("id"));selected=YoutubeClient.compact(info);a.media.pauseMusic();player=new YoutubePlayer(this,info,resume?ra.position(selected.optString("id")):0);a.addContentView(player,new ViewGroup.LayoutParams(-1,-1));player.requestFocus();});}
 void edit(String title,String initial,java.util.function.Consumer<String> save){a.tools.editor=new BladesKeyboard(a,title,initial,1024,false,save,()->{a.tools.editor=null;post(this::requestFocus);});}
 void refresh(){if(screen==1){if(listSource.equals("feed"))feed();else if(!listSource.isEmpty())browse(listSource,listTitle,listPage);else{build();invalidate();}}else{build();invalidate();}}
 void back(){if(player!=null){player.back();return;}ra.cancel();if(screen==0)close();else if(screen==5)page(2);else if(screen==6)page(4);else if(screen==2)page(1);else home();}
 void close(){closed=true;ra.cancel();ra.changed=()->{};if(player!=null)player.close();if(getParent() instanceof ViewGroup)((ViewGroup)getParent()).removeView(this);a.youtubeBrowser=null;a.openJellyfin();}
 int slots(){return Math.max(3,Math.min(9,(int)((height-345)/61)));}
 void move(int n){index=Math.max(0,Math.min(rows.size()-1,index+n));if(index<offset)offset=index;if(index>=offset+slots())offset=index-slots()+1;invalidate();}
 void select(){if(index>=0&&index<rows.size())rows.get(index).run.run();invalidate();}
 @Override public boolean onKeyDown(int key,KeyEvent e){if(e.getRepeatCount()>0&&(key==96||key==97))return true;switch(key){case 19:move(-1);break;case 20:move(1);break;case 102:move(-slots());break;case 103:move(slots());break;case 96:case 66:case 23:select();break;case 97:case 4:back();break;case 99:page(4);break;case 100:refresh();break;}return true;}
 @Override public boolean onKeyUp(int key,KeyEvent e){return true;}
 @Override public boolean onGenericMotionEvent(MotionEvent e){float y=e.getAxisValue(16);if(Math.abs(y)<.5f)y=e.getAxisValue(1);long now=android.os.SystemClock.uptimeMillis();if(Math.abs(y)<.5f){stick=0;return true;}if(now-stick>180){move(y>0?1:-1);stick=now;}return true;}
  void text(Canvas c,String s,float x,float y,float size,int color){p.setShader(null);p.setColor(color);p.setTypeface(a.dashboard.regular);p.setTextSize(size);c.drawText(s,x,y,p);}
  String fit(String s,float width,float size){p.setTypeface(a.dashboard.regular);p.setTextSize(size);if(p.measureText(s)<=width)return s;int n=s.length();while(n>0&&p.measureText(s.substring(0,n)+"…")>width)n--;return s.substring(0,n)+"…";}
  void gradient(Canvas c,RectF r,int top,int bottom,float radius){p.setShader(new LinearGradient(r.left,r.top,r.left,r.bottom,top,bottom,Shader.TileMode.CLAMP));c.drawRoundRect(r,radius,radius,p);p.setShader(null);}
  void button(Canvas c,float x,float y,String letter,String label,int color){p.setShader(new RadialGradient(x-4,y-5,17,new int[]{0xfff5f7de,color,0xff60543b},null,Shader.TileMode.CLAMP));c.drawCircle(x,y,15,p);p.setShader(null);text(c,letter,x-8,y+8,23,Color.WHITE);text(c,label,x+24,y+8,24,0xfffff9e9);}
  void wrapped(Canvas c,String s,float x,float y,float width,float size,float bottom){for(String paragraph:s.split("\n",-1)){String line="";for(String word:paragraph.split(" ")){p.setTextSize(size);if(p.measureText(line+" "+word)>width&&!line.isEmpty()){if(y>bottom)return;text(c,line,x,y,size,0xff17344e);y+=size+6;line=word;}else line=line.isEmpty()?word:line+" "+word;}if(y>bottom)return;text(c,line,x,y,size,0xff17344e);y+=size+6;}}
  @Override protected void onDraw(Canvas c){scale=Math.min(getWidth()/1280f,getHeight()/720f);height=getHeight()/scale;left=(getWidth()-1280*scale)/2;c.drawColor(0xff87908c);c.save();c.translate(left,0);c.scale(scale,scale);
    gradient(c,new RectF(88,0,1195,height),0xff5688b8,0xffc8e0eb,0);
    for(int side=0;side<2;side++){c.save();if(side==1){c.translate(1280,0);c.scale(-1,1);}Path rail=new Path();rail.moveTo(0,0);rail.lineTo(92,0);rail.cubicTo(83,50,78,91,96,110);rail.cubicTo(112,125,104,height*.7f,90,height*.8f);rail.cubicTo(73,height*.9f,81,height*.96f,85,height);rail.lineTo(0,height);rail.close();c.clipPath(rail);p.setShader(new LinearGradient(0,0,110,0,new int[]{0xff465665,0xffe9eff5,0xff9baaba,0xffe3eaf0,0xff475665},null,Shader.TileMode.CLAMP));c.drawRect(0,0,120,height,p);p.setShader(null);c.restore();}
    c.save();c.translate(48,135);c.rotate(90);text(c,"media",0,0,25,0xff27323d);c.restore();c.save();c.translate(1225,135);c.rotate(90);text(c,"media center",0,0,25,0xff27323d);c.restore();
    gradient(c,new RectF(100,-20,1180,96),0xff152f59,0xff315e9e,28);text(c,"Media Center",128,60,38,0xfff0f7ff);text(c,"YouTube",1000,58,28,0xffdceaf5);
    text(c,fit(heading,1000,30),130,145,30,0xff17344e);text(c,fit("Public videos · your local library",1000,22),130,181,22,0xff284e6b);
    for(int i=offset;i<Math.min(rows.size(),offset+slots());i++){float y=215+(i-offset)*61;Item item=rows.get(i);if(i==index)gradient(c,new RectF(123,y-2,669,y+56),0xffe8f5fa,0xff9cc5df,10);text(c,fit(item.title,500,25),140,y+25,25,0xff17344e);text(c,fit(item.sub,500,18),140,y+48,18,0xff315772);p.setColor(0x55496c85);c.drawLine(132,y+59,662,y+59,p);}
    if(offset>0)text(c,"▲",638,205,20,0xff315772);if(offset+slots()<rows.size())text(c,"▼",638,220+slots()*61,20,0xff315772);
    if(!rows.isEmpty()){Item item=rows.get(Math.min(index,rows.size()-1));gradient(c,new RectF(716,215,1146,height-130),0x99dcedfa,0x669fc0d5,12);float bodyY=254;Bitmap art=ra.image(item.image);if(art!=null){float h=150,w=h*art.getWidth()/art.getHeight();if(w>300){w=300;h=w*art.getHeight()/art.getWidth();}p.setColor(Color.WHITE);c.drawBitmap(art,null,new RectF(748,240,748+w,240+h),p);bodyY=270+h;}wrapped(c,item.body,744,bodyY,370,24,height-150);}
    gradient(c,new RectF(100,height-104,1180,height+20),0xff82afcc,0xffbdd8e8,20);button(c,150,height-45,"A","Select",0xff7eaf3c);button(c,330,height-45,"B","Back",0xffbb4436);button(c,490,height-45,"Y","Refresh",0xffd2b747);button(c,710,height-45,"X","Settings",0xff368dc2);text(c,fit(ra.status,1000,18),135,height-78,18,0xff294f6a);c.restore();}
  @Override public boolean onTouchEvent(MotionEvent e){float x=(e.getX()-left)/scale,y=e.getY()/scale;if(e.getAction()==0){down=y;return true;}if(e.getAction()!=1)return true;if(Math.abs(y-down)>45){move(y<down?slots():-slots());return true;}if(y>height-65){if(x<290)select();else if(x<440)back();else if(x<680)refresh();else page(4);return true;}if(x<110){back();return true;}if(x<680&&y>=215){int n=offset+(int)((y-215)/61);if(n<rows.size()&&n<offset+slots()){if(n==index)select();else{index=n;invalidate();}}}return true;}
}
